#include "tigersheets/main_window.hpp"
#include "tigersheets/financial_model_pane.hpp"
#include "tigersheets/grid.hpp"
#include "tigersheets/ooxml.hpp"
#include <QApplication>
#include <QComboBox>
#include <QDockWidget>
#include <QElapsedTimer>
#include <QLabel>
#include <QPushButton>
#include <QTableView>
#include <cmath>
#include <QTemporaryDir>
#include <QtTest/QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool value,const std::string& message){if(!value)throw std::runtime_error(message);}
template<class T>T* child(QObject& owner,const char* name){auto* result=owner.findChild<T*>(name);require(result,std::string("missing control ")+name);return result;}
FinancialModelPane* pane(MainWindow& window){for(auto* widget:window.findChildren<QWidget*>())if(auto* result=dynamic_cast<FinancialModelPane*>(widget))return result;throw std::runtime_error("missing financial authoring pane");}
Json at(int row){return {{"sheet","sheet-1"},{"row",row},{"col",2}};}
Json destination(int row){return {{"sheet","sheet-2"},{"row1",row},{"col1",1}};}
Json inputSet(const std::string& id,double revenue){auto input=at(2);input["type"]="number";input["value"]=revenue;return {{"version",1},{"id",id},{"name",id=="base"?"Base":"Upside"},{"kind","scenario"},{"cells",Json::array({input})}};}
void waitPreview(MainWindow& window){QElapsedTimer timer;timer.start();while(!window.currentSession().hasPreview()&&timer.elapsed()<15000){QCoreApplication::processEvents();QTest::qWait(1);if(!window.property("financialBusy").toBool()&&!window.lastError().isEmpty())break;}require(window.currentSession().hasPreview(),std::string("native financial preview: ")+window.lastError().toStdString());require(child<QPushButton>(*pane(window),"financial.accept")->isEnabled(),"qualified native preview enables Accept");}
void accept(MainWindow& window){QTest::mouseClick(child<QPushButton>(*pane(window),"financial.accept"),Qt::LeftButton);require(!window.currentSession().hasPreview(),"pane Accept commits the candidate");}
void run(MainWindow& window,const Json& definition,bool save=false){pane(window)->setDefinition(definition);QTest::mouseClick(child<QPushButton>(*pane(window),save?"financial.save":"financial.run"),Qt::LeftButton);waitPreview(window);}
const Json& saved(const Json& book,const std::string& id){for(const auto& model:book.at("financialModels"))if(model.at("id")==id)return model;throw std::runtime_error("missing saved setup "+id);}
Json sourceBook(){return {{"revision",0},{"sheets",Json::array({{{"id","sheet-1"},{"name","Operating model"},{"cells",Json::array({{{"row",1},{"col",1},{"input","Native desktop financial acceptance"}},{{"row",2},{"col",1},{"input","Revenue"}},{{"row",2},{"col",2},{"input","100"}},{{"row",3},{"col",1},{"input","Growth"}},{{"row",3},{"col",2},{"input","0.1"},{"style",{{"numberFormat","0.0%"}}}},{{"row",4},{"col",1},{"input","Forecast revenue"}},{{"row",4},{"col",2},{"input","=B2*(1+B3)"},{"style",{{"numberFormat","$#,##0.00"}}}}})}},{{"id","sheet-2"},{"name","Financial reports"},{"cells",Json::array()}}})}};}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir directory;qputenv("TIGERSHEETS_STATE_DIR",directory.path().toUtf8());try{require(argc>1,"supply the actual native report-worker path");MainWindow window;window.setProperty("reportWorkerExecutable",QString::fromLocal8Bit(argv[1]));const auto fixture=directory.filePath("model.xlsx");writeWorkbook(fixture.toStdString(),sourceBook());require(window.openWorkbook(fixture),window.lastError().toStdString());window.resize(1400,950);window.show();require(QTest::qWaitForWindowExposed(&window),"actual application window is exposed");require(window.executeCommand("financial.forecast"),"Forecast ribbon command opens native authoring");auto* fields=pane(window);for(auto* dock:window.findChildren<QDockWidget*>())if(dock->widget()==fields)window.resizeDocks({dock},{440},Qt::Horizontal);QCoreApplication::processEvents();auto& session=window.currentSession();const auto originalSheets=session.snapshotView().at("sheets");Json forecast={{"version",1},{"id","forecast"},{"name","Desktop revenue forecast"},{"kind","forecast"},{"periods",3},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",at(2)},{"growth",at(3)},{"numberFormat","$#,##0.00"}}})},{"output",destination(1)}};run(window,forecast);require(session.snapshotView().at("sheets")==originalSheets,"native forecast calculation does not mutate live source/destination before acceptance");const auto previewId=session.previewView()->at("financialModels")[0].at("id");const bool changed=window.executeCommand("financial.goal_seek");require(!changed||(fields->definition().at("kind")=="forecast"&&child<QPushButton>(*fields,"financial.accept")->isEnabled()&&child<QLabel>(*fields,"financial.status")->text().contains("preview",Qt::CaseInsensitive)),"opening another financial family must preserve or refuse the active qualified preview");require(session.previewView()->at("financialModels")[0].at("id")==previewId,"a family command cannot replace the pending native candidate");accept(window);require(saved(session.snapshotView(),"forecast").at("results")[0][2].get<double>()>133.09,"native accepted forecast stores calculated results");require(window.executeCommand("undo")&&session.snapshotView().at("sheets")==originalSheets&&!session.snapshotView().contains("financialModels"),"one desktop Undo restores source and empty report together");require(window.executeCommand("redo"),"desktop Redo restores report");require(window.executeCommand("financial.open"),"saved authoring pane reopens");auto* picker=child<QComboBox>(*fields,"financial.saved");picker->setCurrentIndex(picker->findData("forecast"));require(fields->definition().at("id")=="forecast","saved picker reloads accepted editable setup");auto* grid=child<QTableView>(window,"worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model,"actual worksheet model");require(model->apply(Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",3},{"col",2},{"input","0.2"}}})),"source growth edit is accepted");require(picker->currentText().contains("Stale"),"live source edits expose saved report freshness");QTest::mouseClick(child<QPushButton>(*fields,"financial.run"),Qt::LeftButton);waitPreview(window);accept(window);require(std::abs(saved(session.snapshotView(),"forecast").at("results")[0][0].get<double>()-120)<1e-6,"saved native forecast refresh uses the edited source");
 run(window,inputSet("base",100),true);accept(window);run(window,inputSet("up",200),true);accept(window);auto output=at(4);output["label"]="Revenue";output["numberFormat"]="$#,##0.00";Json comparison={{"version",1},{"id","comparison"},{"name","Desktop comparison"},{"kind","scenario_comparison"},{"scenarioIds",Json::array({"base","up"})},{"outputs",Json::array({output})},{"output",destination(10)}};run(window,comparison);require(session.cellAt("sheet-1",2,2)->at("input")=="100","native scenario comparison preserves live trial inputs");accept(window);require(std::abs(saved(session.snapshotView(),"comparison").at("results")[2][0].get<double>()-240)<1e-6,"native comparison calculates independent Upside result");auto changing=at(3);changing["values"]=Json::array({0.1,0.2});Json sensitivity={{"version",1},{"id","sensitivity"},{"name","Desktop sensitivity"},{"kind","sensitivity"},{"inputs",Json::array({changing})},{"result",output},{"output",destination(20)}};run(window,sensitivity);accept(window);require(std::abs(saved(session.snapshotView(),"sensitivity").at("results")[0][0].get<double>()-110)<1e-6,"native sensitivity delivers independently expected trial value");
 const auto oldSheetCount=session.snapshotView().at("sheets").size();require(window.executeCommand("financial.example"),"empty-argument circular example command starts native work");waitPreview(window);require(session.snapshotView().at("sheets").size()==oldSheetCount&&session.previewView()->at("sheets").size()==oldSheetCount+2,"real circular example adds two sheets only inside preview");accept(window);require(session.snapshotView().at("sheets").size()==oldSheetCount+2,"accept publishes complete circular example");require(window.executeCommand("financial.delete",{{"definition",{{"id","sensitivity"}}}}),"id-only saved-report deletion starts native preview");waitPreview(window);require(saved(session.snapshotView(),"sensitivity").at("id")=="sensitivity","delete preview retains live report until acceptance");require(window.executeCommand("preview.discard"),"native deletion can be discarded");require(saved(session.snapshotView(),"sensitivity").at("id")=="sensitivity","discard keeps saved setup and report");require(window.executeCommand("financial.open"),"open final authoring view");picker->setCurrentIndex(picker->findData("forecast"));std::cout<<"native desktop financial acceptance passed: forecast, saved refresh, scenario comparison, sensitivity, circular example, id-only delete; preview/accept/undo/discard\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
